public class Solution{bool F(char[][]b,int i,int j,string w,int k){if(k==w.Length)return true;if(i<0||j<0||i==b.Length||j==b[0].Length||b[i][j]!=w[k])return false;char c=b[i][j];b[i][j]='\0';bool ok=F(b,i+1,j,w,k+1)||F(b,i-1,j,w,k+1)||F(b,i,j+1,w,k+1)||F(b,i,j-1,w,k+1);b[i][j]=c;return ok;}public bool Exist(char[][]b,string w){for(int i=0;i<b.Length;i++)for(int j=0;j<b[0].Length;j++)if(F(b,i,j,w,0))return true;return false;}}
